# AtomicAndPhysicalConstants/src/CODATA2014.jl
# Constants pulled from the NIST table of
# the 2014 CODATA release
# Generated by update/update_constants.jl; masses are NIST's
# "energy equivalent in MeV" values with the decimal point moved to eV.



#####################################################################
# Physical constants
#####################################################################


"""
    CODATA2014 :: CODATA_release

Fundamental constants from the 2014 CODATA release.

See [NIST CODATA](https://physics.nist.gov/cuu/Constants/) for the
primary source values.
"""
const CODATA2014 = CODATA_release(

#######################################
# constants with dimension [mass]
#######################################


M_ELECTRON = 510998.9461,
# Electron Mass [eV]/c^2
M_PROTON = 9.382720813e8,
# Proton Mass [eV]/c^2
M_NEUTRON = 9.395654133e8,
# Neutron Mass [eV]/c^2
M_MUON = 1.056583745e8,
# Muon Mass [eV]/c^2
M_HELION = 2.808391586e9,
# Helion Mass He3 nucleus [eV]/c^2
M_DEUTERON = 1.875612928e9,
# Deuteron Mass [eV]/c^2
M_TRITON = 2.808921112e9,
# Triton Mass [eV]/c^2

# constants mysteriously missing from the release
# picked up from PDG
M_PION_0 = 1.349768277676847e8,
# uncharged pion mass [eV]/c^2
M_PION_CHARGED = 1.3957039098368132e8,
# charged pion mass [eV]/c^2


#######################################
# constants with dimension [magnetic moment]
#######################################


MU_DEUTERON = 4.33073504e-27,
# deuteron magnetic moment in [J/T]
MU_ELECTRON = -9.28476462e-24,
# electron magnetic moment in [J/T]
MU_HELION = -1.074617522e-26,
# helion magnetic moment in [J/T]
MU_MUON = -4.49044826e-26,
# muon magnetic moment in [J/T]
MU_NEUTRON = -9.662365e-27,
# neutron magnetic moment in [J/T]
MU_PROTON = 1.4106067873e-26,
# proton magnetic moment in [J/T]
MU_TRITON = 1.504609503e-26,
# triton magnetic moment in [J/T]


#######################################
# dimensionless constants
#######################################


AVOGADRO = 6.022140857e23,
# Avogadro's constant: Number / mole (exact)
FINE_STRUCTURE = 0.0072973525664,
# fine structure constant

ANOMALY_ELECTRON = 0.00115965218091,
# electron magnetic moment anomaly
ANOMALY_MUON = 0.00116592089,
# muon magnetic moment anomaly

G_DEUTERON_NUCLEAR = 0.8574382311,
# deuteron g factor
G_ELECTRON = -2.00231930436182,
# electron g factor
G_HELION_NUCLEAR = -4.255250616,
