#######################################
# constants with miscellaneous dimension
#######################################


E_CHARGE = 1.6021766208e-19,
# elementary charge [C]
R_ELECTRON = 2.8179403227e-15,
# classical electron radius [m]
R_PROTON = 1.5346982647904073e-18,
# classical proton radius [m], R_ELECTRON * M_ELECTRON / M_PROTON
C_LIGHT = 2.99792458e8,
# speed of light [m/s]
H_PLANCK = 4.135667662e-15,
# Planck's constant [eV*s]
H_BAR = 6.582119514e-16,
# h_planck/twopi [eV*s]

K_BOLTZMANN = 8.6173303e-5,
#k_B in eV/K

EPS_0 = 5.526349406208986e7,
# Permittivity of free space in [1/(eV*m)]
MU_0 = 2.013354520605894e-25,
