J_PER_EV = 1.6021766208e-19,
# Joules per eV

EV_PER_J = 6.241509126e18,
# eV per Joule

G_PER_EV = 1.782661907e-33,
# grams per eV/c^2

RELEASE_YEAR = 2014


)

